/// <summary>
/// PaffH 03.08.22
/// </summary>
/// <param name = "_refTableId">RefTableId</param>
/// <param name = "_refRecId">RefRecId</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXDataTransferError</returns>
public static NDXDataTransferError find(RefTableId _refTableId, RefRecId _refRecId, boolean _forUpdate = true)
{
    NDXDataTransferError nDXDataTransferError;
    nDXDataTransferError.selectForUpdate(_forUpdate);
    select firstonly nDXDataTransferError
        where nDXDataTransferError.RefTableId == _refTableId
        && nDXDataTransferError.RefRecId == _refRecId;
    return nDXDataTransferError;
}

/// <summary>
/// PaffH 03.08.22
/// </summary>
/// <param name = "_refTableId">RefTableId</param>
/// <param name = "_refRecId">RefRecId</param>
/// <param name = "_doInsert">boolean</param>
/// <returns>NDXDataTransferError</returns>
public static NDXDataTransferError findOrCreate(RefTableId _refTableId, RefRecId _refRecId, boolean _doInsert = true)
{
    NDXDataTransferError nDXDataTransferError;
    nDXDataTransferError = NDXDataTransferError::find(_refTableId, _refRecId, true);
    if (!nDXDataTransferError)
    {
        nDXDataTransferError.RefTableId = _refTableId;
        nDXDataTransferError.RefRecId = _refRecId;
        if (_doInsert)
        {
            nDXDataTransferError.insert();
        }
    }
    return nDXDataTransferError;
}

/// <summary>
/// PaffH 10.08.22
/// </summary>
/// <param name = "_refTableId">RefTableId</param>
/// <param name = "_refRecId">RefRecId</param>
/// <param name = "_doInsert">boolean</param>
/// <returns>NDXDataTransferError</returns>
public static NDXDataTransferError create(RefTableId _refTableId, RefRecId _refRecId, boolean _doInsert = true)
{
    NDXDataTransferError nDXDataTransferError;
    nDXDataTransferError.RefTableId = _refTableId;
    nDXDataTransferError.RefRecId = _refRecId;
    if (_doInsert)
    {
        nDXDataTransferError.insert();
    }
    return nDXDataTransferError;
}

/// <summary>
/// PaffH 03.08.22
/// insert new Errormessage
/// </summary>
/// <param name = "_refTableId">RefTableId</param>
/// <param name = "_refRecId">RefRecId</param>
/// <param name = "_errorMessage">NDXErrorMessageMemo</param>
public static void saveError(RefTableId _refTableId, RefRecId _refRecId, NDXErrorMessageMemo _errorMessage)
{
    NDXDataTransferError  nDXDataTransferError = nDXDataTransferError::create(_refTableId, _refRecId, true);
    NDXDataTransferErrorLine nDXDataTransferErrorLine;
    nDXDataTransferErrorLine.NDXDataTransferError = nDXDataTransferError.RecId;
    nDXDataTransferErrorLine.ErrorMessage = _errorMessage;
    nDXDataTransferErrorLine.insert();
}

/// <summary>
/// PaffH 20.04.23
/// count not solved errors
/// </summary>
/// <returns>not solved errors</returns>
public display Counter CountNotSolvedErrors()
{
    NDXDataTransferErrorLine nDXDataTransferErrorLine;
    select count(RecId) from nDXDataTransferErrorLine
        where nDXDataTransferErrorLine.NDXDataTransferError == this.RecId
            && nDXDataTransferErrorLine.ErrorDone == NoYes::No;
    if (this.CounterErrorMessages != nDXDataTransferErrorLine.RecId)
    {
        this.selectForUpdate(true);
        this.CounterErrorMessages = int642int(nDXDataTransferErrorLine.RecId);
        ttsbegin;
        this.update();
        ttscommit;
    }
    return int642int(nDXDataTransferErrorLine.RecId);
}
